import{_ as a,o as i,c as n,a1 as t}from"./chunks/framework.D8yXMOOQ.js";const g=JSON.parse('{"title":"Baseline Management","description":"","frontmatter":{},"headers":[],"relativePath":"baseline.md","filePath":"baseline.md"}'),s={name:"baseline.md"};function o(l,e,r,h,d,c){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="baseline-management" tabindex="-1">Baseline Management <a class="header-anchor" href="#baseline-management" aria-label="Permalink to &quot;Baseline Management&quot;">​</a></h1><p>When introducing Laravel Integrity to an existing, large codebase, you might be overwhelmed by hundreds of hygiene issues or orphaned views.</p><p>Instead of fixing everything at once, you can generate a <em>baseline</em>. This will snapshot all existing issues and ignore them in future checks, allowing you to enforce strict rules only for <em>new</em> code.</p><h2 id="generating-a-baseline" tabindex="-1">Generating a Baseline <a class="header-anchor" href="#generating-a-baseline" aria-label="Permalink to &quot;Generating a Baseline&quot;">​</a></h2><p>To generate a baseline, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integrity:baseline</span></span></code></pre></div><p>This will scan your entire project, find all issues, and save them to a <code>nintegrity-baseline.json</code> file in your project root.</p><h2 id="committing-the-baseline" tabindex="-1">Committing The Baseline <a class="header-anchor" href="#committing-the-baseline" aria-label="Permalink to &quot;Committing The Baseline&quot;">​</a></h2><p>You should commit the <code>.integrity-baseline.json</code> file to your git repository. This ensures that CI/CD pipelines and other developers on your team share the same baseline.</p><h2 id="updating-the-baseline" tabindex="-1">Updating The Baseline <a class="header-anchor" href="#updating-the-baseline" aria-label="Permalink to &quot;Updating The Baseline&quot;">​</a></h2><p>As you gradually fix legacy issues, the baseline will automatically shrink if you rerun the baseline command.</p><p>It is a good practice to occasionally rerun <code>artisan integrity:baseline</code> to keep the file up to date as technical debt is resolved.</p>',12)])])}const u=a(s,[["render",o]]);export{g as __pageData,u as default};
